@pytest.mark.parametrize("qt_version, checks", [
    ("6.2.2", {"6.2.3": False, "6.7.0": False}),
    ("6.7.0", {"6.2.3": True, "6.7.0": True}),
])
def test_suffixes_workaround_outside_qt_range(monkeypatch, qt_version, checks):
    def version(string):
        return checks[string]

    class UnreadableMimetypes:
        def __iter__(self):
            raise AssertionError("MIME types were inspected before the Qt version")

    monkeypatch.setattr(qtutils, "version_check", version)
    assert webview.extra_suffixes_workaround(UnreadableMimetypes()) == set(), qt_version


